#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, K;
    cin >> N >> K;

    vector<int> T(N);
    for (int &x : T) cin >> x;
    sort(T.begin(), T.end());

    int M = N - K;
    const long long INF = LLONG_MAX / 4;

    vector<long long> dp_im2(K + 1, INF), dp_im1(K + 1, INF);
    dp_im2[0] = dp_im1[0] = 0;

    for (int i = 2; i <= M; ++i) {
        vector<long long> dp_i = dp_im1;
        long long diff = T[i - 1] - T[i - 2];
        long long cost = diff * diff;

        for (int j = 1; j <= min(K, i / 2); ++j) {
            if (dp_im2[j - 1] != INF) {
                dp_i[j] = min(dp_i[j], dp_im2[j - 1] + cost);
            }
        }

        dp_im2.swap(dp_im1);
        dp_im1.swap(dp_i);
    }

    cout << dp_im1[K] << '\n';
    return 0;
}
